# Import groupby from itertools

from itertools import groupby

# Goal: with groupby, filter the list by either name, author or publication year
# User should be able to pick the key

key = input("Filter by: ").lower()




# List of books generated by AI

books = [
    {"name": "1984", "publication_year": 1949, "author": "George Orwell"},
    {"name": "The Hobbit", "publication_year": 1937, "author": "J. R. R. Tolkien"},
    {"name": "Pride and Prejudice", "publication_year": 1813, "author": "Jane Austen"},
    {"name": "It", "publication_year": 1986, "author": "Stephen King"},
    {"name": "The Last Man", "publication_year": 1826, "author": "Mary Shelley"},
    {"name": "The Hunger Games", "publication_year": 2008, "author": "Suzanne Collins"},
    {"name": "The Great Gatsby", "publication_year": 1925, "author": "F. Scott Fitzgerald"},
    {"name": "The War of the Worlds", "publication_year": 1898, "author": "H. G. Wells"},
    {"name": "Harry Potter and the Chamber of Secrets", "publication_year": 1998, "author": "J. K. Rowling"},
    {"name": "Adventures of Huckleberry Finn", "publication_year": 1884, "author": "Mark Twain"},
    {"name": "The Shining", "publication_year": 1977, "author": "Stephen King"},
    {"name": "Sense and Sensibility", "publication_year": 1811, "author": "Jane Austen"},
    {"name": "The Fellowship of the Ring", "publication_year": 1954, "author": "J. R. R. Tolkien"},
    {"name": "Animal Farm", "publication_year": 1945, "author": "George Orwell"},
    {"name": "Frankenstein", "publication_year": 1818, "author": "Mary Shelley"},
    {"name": "Catching Fire", "publication_year": 2009, "author": "Suzanne Collins"},
    {"name": "Tender Is the Night", "publication_year": 1934, "author": "F. Scott Fitzgerald"},
    {"name": "The Time Machine", "publication_year": 1895, "author": "H. G. Wells"},
    {"name": "Harry Potter and the Philosopher's Stone", "publication_year": 1997, "author": "J. K. Rowling"},
    {"name": "The Adventures of Tom Sawyer", "publication_year": 1876, "author": "Mark Twain"}
]


# Create a function that defines the key

def sorting(value):
    return lambda b:b[value]



try:
# 1. sort the dictionnary by key (ex. author)
    books_sorted = sorted(books, key = sorting(key))


# 2. group the dictionaries by key
    books_grouped =  groupby(books_sorted, key = sorting(key)) 
    
except KeyError:
    print(key, "key does not exist in the dictionary")

else:
        # 3. Print the result
    for key, values in books_grouped:
        print(key.upper())
        for value in values:
            print(value)
        











